public class GetUser : Endpoint<GetUserRequest, UserResponse>
{
    public override void Configure() => Get("/users/{id}");

    public override async Task HandleAsync(GetUserRequest r, CancellationToken ct)
    {
        var u = await users.FindAsync(r.Id);          // domain
        if (u is null) { await SendNotFoundAsync(ct); return; }
        await SendAsync(new UserResponse(u.Id, u.Name), cancellation: ct);  // responder
    }
}
